SELECT custom_role_id, tenant_id, role_name, status, version, created_at, disabled_at
FROM organization_access.tenant_custom_role
WHERE tenant_id = #{tenantId}
  AND custom_role_id = #{customRoleId}
  AND status = 'ACTIVE'
FOR UPDATE

SELECT count(*)
FROM organization_access.tenant_custom_role_binding
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
  AND custom_role_id = #{customRoleId}
